package nl.dwmarketing.callerid;
import android.app.*;import android.app.role.*;import android.os.*;import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.text.InputType;import android.view.*;import android.widget.*;
public final class SetupActivity extends Activity {
 private TextView status;private EditText email,password;private boolean busy;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,48,32,32);ScrollView scroll=new ScrollView(this);scroll.addView(box);setContentView(scroll);
  label(box,"DW Nummerherkenning TEST 0.4 · alleen Dennis");
  status=new TextView(this);status.setTextSize(18);status.setPadding(0,12,0,12);box.addView(status);showSnapshot();
  label(box,"Samsung Telefoon blijft je bel-app. Herkenning gebruikt uitsluitend je eigen DW Flow. Geen blokkeren, opnemen of externe nummerdienst.");
  button(box,"1. Apparaat koppelen: openbare sleutel kopiëren",()->{try{String pub=PrivateStore.publicKey();getSystemService(ClipboardManager.class).setPrimaryClip(ClipData.newPlainText("DW openbare apparaatcode",pub));status.setText("Openbare apparaatcode gekopieerd. Koppel deze aan je eigenaarsaccount voordat je synchroniseert.");}catch(Exception e){status.setText("Apparaatsleutel niet beschikbaar.");}});
  label(box,"Meld je aan met je bestaande DW-account. Deel je wachtwoord niet in de chat.");email=new EditText(this);email.setHint("DW e-mailadres");email.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);box.addView(email);password=new EditText(this);password.setHint("Wachtwoord");password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(password);
  button(box,"2. Aanmelden en synchroniseren",()->{String mail=email.getText().toString().trim(),pw=password.getText().toString();if(mail.isEmpty()||pw.isEmpty()){status.setText("Vul je DW e-mailadres en wachtwoord in.");return;}password.setText("");sync(()->SyncClient.login(this,mail,pw));});
  button(box,"3. DW als nummerherkenning kiezen",()->{RoleManager manager=getSystemService(RoleManager.class);if(!manager.isRoleAvailable(RoleManager.ROLE_CALL_SCREENING)){status.setText("Nummerherkenning niet beschikbaar op dit toestel.");return;}if(!manager.isRoleHeld(RoleManager.ROLE_CALL_SCREENING))startActivityForResult(manager.createRequestRoleIntent(RoleManager.ROLE_CALL_SCREENING),10);else status.setText("DW is al gekozen voor nummerherkenning.");});
  button(box,"4. Meldingen toestaan",()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},11);else status.setText("Meldingentoestemming is al verleend. Controleer eventueel de meldinginstellingen van Android.");});
  label(box,"Optioneel: nummers herkennen die al in je telefooncontacten staan. Android vereist contacttoegang; deze app leest of uploadt je telefooncontacten niet.");
  button(box,"Herkennen binnen opgeslagen telefooncontacten",()->requestPermissions(new String[]{Manifest.permission.READ_CONTACTS},12));
  button(box,"Nu bijwerken",()->sync(()->SyncClient.sync(this)));
  button(box,"Laatste synchronisatie controleren",()->showSnapshot());
  button(box,"Afmelden en lokale klantgegevens wissen",()->{if(busy)return;new AlertDialog.Builder(this).setMessage("Alleen lokale DW-sessie en klantlijst wissen? Je DW Flow-dossiers blijven behouden.").setNegativeButton("Annuleren",null).setPositiveButton("Afmelden",(d,w)->{SyncClient.logout(this);status.setText("Afgemeld. Lokale sessie en klantlijst gewist; DW Flow is ongewijzigd.");}).show();});
 }
 interface Job {void run()throws Exception;}
 private void sync(Job job){if(busy)return;busy=true;status.setText("Synchroniseren…");new Thread(()->{try{job.run();boolean automatic=false;try{automatic=SyncJob.schedule(this);}catch(RuntimeException ignored){}final boolean scheduled=automatic;runOnUiThread(()->{showSnapshot();status.append(scheduled?"\nAutomatisch verversen ingepland. Android bepaalt wanneer de achtergrondtaak mag draaien.":"\nSynchronisatie geslaagd, maar automatisch verversen kon niet worden ingepland. Gebruik voorlopig Nu bijwerken.");busy=false;});}catch(Exception e){runOnUiThread(()->{status.setText("Synchronisatie niet bevestigd. Controleer account, apparaatkoppeling en verbinding. Je DW Flow-dossiers zijn ongewijzigd.");busy=false;});}},"dw-setup").start();}
 private void showSnapshot(){try{org.json.JSONObject s=PrivateStore.get(this,"snapshot");if(s==null){status.setText("Nog geen klantlijst. Koppel je toestel en meld je aan.");return;}long time=s.getLong("synced_at"),expires=s.getLong("expires_at");status.setText((expires>System.currentTimeMillis()?"Klantlijst bijgewerkt: ":"Klantlijst verlopen. Tik Nu bijwerken. Laatste update: ")+java.text.DateFormat.getDateTimeInstance().format(new java.util.Date(time)));}catch(Exception e){status.setText("Lokale klantlijst niet leesbaar. Synchroniseer opnieuw.");}}
 private void label(LinearLayout box,String value){TextView t=new TextView(this);t.setText(value);t.setTextSize(17);t.setPadding(0,12,0,12);box.addView(t);}
 private void button(LinearLayout box,String value,Runnable action){Button b=new Button(this);b.setText(value);b.setMinHeight(56);b.setOnClickListener(v->action.run());box.addView(b);}
}
